import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { Shift } from '@/types/database'

// Threshold above which a manager PIN is required to close shift
export const VARIANCE_PIN_THRESHOLD = 100_000

const STORAGE_KEY = 'mock_current_shift'
const PAYMENTS_KEY = 'mock_shift_payments'

// ─── Mock payments (generated when a shift is opened) ───────────────
const MOCK_PAYMENTS: Array<{ amount: number; method: string }> = [
  { amount: 350000, method: 'cash' },
  { amount: 200000, method: 'cash' },
  { amount: 500000, method: 'card' },
  { amount: 300000, method: 'transfer' },
  { amount: 150000, method: 'cash' },
  { amount: 425000, method: 'card' },
  { amount: 180000, method: 'cash' },
]

function createMockShift(branchId: string, openingCash: number, userId: string, notes?: string): Shift {
  const now = new Date().toISOString()
  return {
    id: `mock-shift-${Date.now()}`,
    branch_id: branchId,
    user_id: userId,
    status: 'open',
    opened_at: now,
    closed_at: null,
    opening_cash: openingCash,
    closing_cash: null,
    expected_cash: null,
    cash_difference: null,
    notes: { handover_notes: '', open_shift_notes: notes ?? '' } as any,
    metadata: { opened_via: 'mock' },
    created_at: now,
    updated_at: now,
  }
}

function loadFromStorage(): Shift | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    return raw ? (JSON.parse(raw) as Shift) : null
  } catch {
    return null
  }
}

function saveToStorage(shift: Shift | null) {
  try {
    if (shift) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(shift))
    } else {
      localStorage.removeItem(STORAGE_KEY)
    }
  } catch {
    // ignore
  }
}

function loadPaymentsFromStorage(): any[] {
  try {
    const raw = localStorage.getItem(PAYMENTS_KEY)
    return raw ? (JSON.parse(raw) as any[]) : []
  } catch {
    return []
  }
}

function savePaymentsToStorage(payments: any[]) {
  try {
    localStorage.setItem(PAYMENTS_KEY, JSON.stringify(payments))
  } catch {
    // ignore
  }
}

export const useShiftStore = defineStore('shift', () => {
  // ─── State ─────────────────────────────────────────────────────────
  const currentShift = ref<Shift | null>(loadFromStorage())
  const shiftPayments = ref<any[]>(loadPaymentsFromStorage())
  const loading = ref(false)
  const error = ref<string | null>(null)

  // ─── Computed: revenue breakdown ───────────────────────────────────
  const cashRevenue = computed(() =>
    shiftPayments.value
      .filter((p) => p.method === 'cash')
      .reduce((sum, p) => sum + Number(p.amount || 0), 0),
  )

  const cardRevenue = computed(() =>
    shiftPayments.value
      .filter((p) => p.method === 'card')
      .reduce((sum, p) => sum + Number(p.amount || 0), 0),
  )

  const transferRevenue = computed(() =>
    shiftPayments.value
      .filter((p) => p.method === 'transfer')
      .reduce((sum, p) => sum + Number(p.amount || 0), 0),
  )

  const otherRevenue = computed(() =>
    shiftPayments.value
      .filter((p) => !['cash', 'card', 'transfer'].includes(p.method))
      .reduce((sum, p) => sum + Number(p.amount || 0), 0),
  )

  const totalRevenue = computed(
    () => cashRevenue.value + cardRevenue.value + transferRevenue.value + otherRevenue.value,
  )

  const expectedCash = computed(() => {
    if (!currentShift.value) return 0
    return Number(currentShift.value.opening_cash || 0) + cashRevenue.value
  })

  const orderCount = computed(() => shiftPayments.value.length)

  const isOpen = computed(() => currentShift.value?.status === 'open')

  const openingCash = computed(() =>
    currentShift.value ? Number(currentShift.value.opening_cash || 0) : 0,
  )

  // ─── Actions (mock — no API calls) ─────────────────────────────────
  async function fetchActiveShift(_branchId: string) {
    // Load from localStorage (already loaded on init, but refresh in case
    // another tab modified it)
    currentShift.value = loadFromStorage()
  }

  async function fetchShiftPayments() {
    shiftPayments.value = loadPaymentsFromStorage()
  }

  async function refresh(branchId: string) {
    loading.value = true
    error.value = null
    try {
      await fetchActiveShift(branchId)
      await fetchShiftPayments()
    } catch (e) {
      error.value = e instanceof Error ? e.message : String(e)
    } finally {
      loading.value = false
    }
  }

  async function openShift(branchId: string, openingCash: number, notes?: string) {
    loading.value = true
    error.value = null
    try {
      // Simulate async delay
      await new Promise((r) => setTimeout(r, 300))

      const userId = 'mock-user-0001'
      const shift = createMockShift(branchId, openingCash, userId, notes)
      currentShift.value = shift
      saveToStorage(shift)

      // Generate mock payments for this shift
      shiftPayments.value = [...MOCK_PAYMENTS]
      savePaymentsToStorage(shiftPayments.value)

      return {
        ok: true,
        idempotent: false,
        shift: { id: shift.id },
      }
    } catch (e) {
      error.value = e instanceof Error ? e.message : String(e)
      throw e
    } finally {
      loading.value = false
    }
  }

  async function closeShift(closingCash: number, notes?: string) {
    if (!currentShift.value) throw new Error('No active shift')
    loading.value = true
    error.value = null
    try {
      // Simulate async delay
      await new Promise((r) => setTimeout(r, 300))

      const diff = closingCash - expectedCash.value

      const closed: Shift = {
        ...currentShift.value,
        status: 'closed',
        closed_at: new Date().toISOString(),
        closing_cash: closingCash,
        expected_cash: expectedCash.value,
        cash_difference: diff,
        notes: { handover_notes: notes ?? '' } as any,
      }

      currentShift.value = null
      shiftPayments.value = []
      saveToStorage(null)
      savePaymentsToStorage([])

      return {
        ok: true,
        shift: { id: closed.id, closed_at: closed.closed_at },
        expectedCash: closed.expected_cash,
        closingCash,
        cashDifference: diff,
      }
    } catch (e) {
      error.value = e instanceof Error ? e.message : String(e)
      throw e
    } finally {
      loading.value = false
    }
  }

  function reset() {
    currentShift.value = null
    shiftPayments.value = []
    error.value = null
    saveToStorage(null)
    savePaymentsToStorage([])
  }

  return {
    // State
    currentShift,
    shiftPayments,
    loading,
    error,
    // Computed
    cashRevenue,
    cardRevenue,
    transferRevenue,
    otherRevenue,
    totalRevenue,
    expectedCash,
    orderCount,
    isOpen,
    openingCash,
    // Actions
    fetchActiveShift,
    fetchShiftPayments,
    refresh,
    openShift,
    closeShift,
    reset,
  }
})

import { ref } from 'vue'
import { supabase } from '@/lib/supabase'
import { useBranch, throwBranchGuard } from './useBranch'
import type { Notification } from '@/types/database'

export function useNotification() {
  const { activeBranchId } = useBranch()
  const loading = ref(false)
  const error = ref<string | null>(null)

  async function listForRole(role: string, limit = 50): Promise<Notification[]> {
    loading.value = true
    error.value = null
    const { data, error: err } = await supabase
      .from('notifications')
      .select('*')
      .eq('branch_id', (activeBranchId.value ?? throwBranchGuard()))
      .eq('channel', role)
      .order('created_at', { ascending: false })
      .limit(limit)
    loading.value = false
    if (err) {
      error.value = err.message
      throw err
    }
    return (data ?? []) as Notification[]
  }

  async function markRead(id: string): Promise<void> {
    const { error: err } = await supabase
      .from('notifications')
      .update({ status: 'read' })
      .eq('id', id)
    if (err) throw err
  }

  return { loading, error, listForRole, markRead }
}

import { onUnmounted, ref } from 'vue'
import type { RealtimeChannel } from '@supabase/supabase-js'
import { supabase } from '@/lib/supabase'
import { useAuth } from './useAuth'

export type RealtimeEvent = 'INSERT' | 'UPDATE' | 'DELETE' | '*'
export type RealtimeStatus = 'connecting' | 'connected' | 'disconnected' | 'error'

interface ChangePayload<T> {
  eventType: RealtimeEvent | string
  new: T
  old: T
}

type Listener<T> = (payload: ChangePayload<T>) => void

/**
 * Module-level dedup state. Each entry holds:
 *   - ch: the shared RealtimeChannel
 *   - listeners: every subscriber's onChange callback (one per `watchTable`
 *     call). The channel broadcasts every event to all listeners.
 *   - ref: total subscriber count; the channel is torn down only when the
 *     last subscriber unmounts.
 *   - status: the latest channel status from the first subscriber's
 *     `subscribe()` callback so late joiners can adopt it.
 *
 * Why a single Map (instead of separate `channels` and `channelRefs` Maps):
 * the previous design had a silent-bug where a SECOND subscriber to the
 * same `(table, event, filter)` tuple never had its callback wired up —
 * the channel was reused as-is and the new `onChange` was discarded
 * because the `if (!ch)` guard skipped the `.on(...)` call entirely.
 * Now every callback lives in a Set the channel can fan out to.
 */
interface ChannelEntry<T = unknown> {
  ch: RealtimeChannel
  listeners: Set<Listener<T>>
  ref: number
  status: RealtimeStatus
}
const registry = new Map<string, ChannelEntry<any>>()

function buildPgFilter(
  branchId: string | undefined,
  extra?: Record<string, string | number>,
): string | undefined {
  const parts: string[] = []
  if (branchId) parts.push(`branch_id=eq.${branchId}`)
  if (extra) {
    for (const [k, v] of Object.entries(extra)) {
      parts.push(`${k}=eq.${v}`)
    }
  }
  return parts.length ? parts.join(',') : undefined
}

/**
 * Realtime subscriptions helper.
 *
 * `watchTable` deduplicates channels by name so multiple components subscribing
 * to the same `(table, event, filter)` triple share one websocket. Each call
 * bumps the entry's reference count and ADDS the callback to the listener
 * set; the underlying channel is torn down only when the LAST subscriber
 * unmounts. This avoids two bugs we previously had:
 *   1. Silent-disconnect: unmounting one component closed the channel for
 *      everyone else.
 *   2. Lost-callback: a second subscriber's onChange was silently dropped
 *      because the channel was reused without re-wiring.
 */
export function useRealtime() {
  const { branchId } = useAuth()
  const status = ref<RealtimeStatus>('disconnected')
  const activeCleanups = new Set<() => void>()

  function watchTable<T = Record<string, unknown>>(
    table: string,
    event: RealtimeEvent,
    onChange: (payload: ChangePayload<T>) => void,
    filter?: Record<string, string | number>,
  ): () => void {
    const channelName = `watch:${table}:${event}:${JSON.stringify(filter ?? {})}`
    let entry = registry.get(channelName) as ChannelEntry<T> | undefined

    if (!entry) {
      const listeners = new Set<Listener<T>>()
      const ch = supabase
        .channel(channelName)
        .on(
          // `postgres_changes` filter typings don't accept our dynamic filter object.
          'postgres_changes' as never,
          {
            event,
            schema: 'public',
            table,
            filter: buildPgFilter(branchId.value, filter),
          },
          (payload: ChangePayload<T>) => {
            // Fan out to every subscriber. Iterating over a Set is safe
            // while callbacks may themselves remove listeners — a
            // callback that triggers `cleanup()` only removes itself
            // from the local copy thanks to the spread.
            for (const cb of Array.from(listeners)) {
              try { cb(payload) } catch (e) {
                console.warn('[useRealtime] listener threw:', e)
              }
            }
          },
        )
        .subscribe((s) => {
          // The first subscriber owns the channel-level status mirror so
          // late joiners can pick it up.
          const next: RealtimeStatus =
            s === 'SUBSCRIBED' ? 'connected'
              : s === 'CLOSED' ? 'disconnected'
              : s === 'CHANNEL_ERROR' ? 'error'
              : 'connecting'
          entry!.status = next
        })
      entry = { ch, listeners, ref: 0, status: 'connecting' }
      registry.set(channelName, entry)
    }

    entry.listeners.add(onChange)
    entry.ref += 1
    // Adopt the latest channel status so this composable's `status` ref
    // doesn't sit at `disconnected` while the channel is actually live.
    status.value = entry.status

    function cleanup() {
      const e = registry.get(channelName)
      if (!e) return
      e.listeners.delete(onChange)
      e.ref = Math.max(0, e.ref - 1)
      activeCleanups.delete(cleanup)
      if (e.ref <= 0) {
        supabase.removeChannel(e.ch)
        registry.delete(channelName)
      }
    }
    activeCleanups.add(cleanup)
    return cleanup
  }

  function cleanupAll() {
    for (const fn of Array.from(activeCleanups)) fn()
    activeCleanups.clear()
  }

  onUnmounted(cleanupAll)

  return { watchTable, status, cleanupAll }
}

import { ref } from 'vue'
import { supabase } from '@/lib/supabase'
import { callEdgeFunction } from '@/utils/edge'

// NOTE: payload keys MUST match the Edge Function contract (camelCase):
// `supabase/functions/close-shift/index.ts` takes `{ shiftId, closingCash, notes }`
// `supabase/functions/open-shift/index.ts` takes `{ branchId, openingCash, notes }`
// `supabase/functions/export-shift-csv/index.ts` reads `?shiftId=<uuid>` from the
// URL (returns raw CSV text, not JSON).
export interface OpenShiftPayload {
  branchId: string
  openingCash: number
  notes?: Record<string, unknown>
}

export interface ShiftOpenResponse {
  ok: boolean
  idempotent?: boolean
  shift: {
    id: string
    branch_id: string
    user_id: string
    status: 'open' | 'closed'
    opened_at: string
    opening_cash: string | number
  }
}

export interface CloseShiftPayload {
  shiftId: string
  closingCash: number
  notes?: string
}

export interface CloseShiftResponse {
  ok?: boolean
  shift?: { id: string; closed_at: string }
  summary?: Record<string, { count: number; total: number }>
  expectedCash?: number
  closingCash?: number
  cashDifference?: number
  error?: string
}

export interface ExportShiftCsvResponse {
  csv: string
  rowCount: number
}

export function useShift() {
  const loading = ref(false)
  const error = ref<string | null>(null)

  async function openShift(payload: OpenShiftPayload): Promise<ShiftOpenResponse> {
    loading.value = true
    error.value = null
    try {
      // 1. Try Edge Function first
      return await callEdgeFunction<OpenShiftPayload, ShiftOpenResponse>(
        'open-shift',
        payload,
      )
    } catch (edgeErr) {
      console.warn('[useShift] Edge Function open-shift failed, trying direct RPC:', edgeErr)
      // 2. Fallback: call shift_open RPC directly via Supabase client
      try {
        const { data, error: rpcErr } = await supabase.rpc('shift_open', {
          p_branch_id: payload.branchId,
          p_opening_cash: payload.openingCash,
          p_notes: payload.notes ?? {},
        })
        if (rpcErr) throw rpcErr
        if (!data) throw new Error('shift_open RPC returned no data')
        return data as ShiftOpenResponse
      } catch (rpcErr) {
        error.value = rpcErr instanceof Error ? rpcErr.message : String(rpcErr)
        throw rpcErr
      }
    } finally {
      loading.value = false
    }
  }

  async function closeShift(
    payload: CloseShiftPayload,
  ): Promise<CloseShiftResponse> {
    loading.value = true
    error.value = null
    try {
      const res = await callEdgeFunction<CloseShiftPayload, CloseShiftResponse>(
        'close-shift',
        payload,
      )
      // Edge Function may return 200 with { ok: false } for business errors
      // (e.g. unsettled orders)
      if (res && res.ok === false && res.error) {
        throw new Error(res.error)
      }
      return res
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e)
      // Provide a more helpful message for common failures
      if (msg.includes('Failed to fetch') || msg.includes('fetch')) {
        error.value = 'Không thể kết nối đến server. Vui lòng kiểm tra kết nối mạng và thử lại.'
      } else if (msg.includes('unsettled_orders') || msg.includes('chưa thanh toán')) {
        error.value = msg
      } else {
        error.value = msg
      }
      throw e
    } finally {
      loading.value = false
    }
  }

  async function exportCsv(shiftId: string): Promise<string> {
    const { data: sessionData } = await supabase.auth.getSession()
    const token = sessionData.session?.access_token
    const supabaseUrl = import.meta.env.VITE_SUPABASE_URL
    if (!token || !supabaseUrl) {
      throw new Error('Không có session — vui lòng đăng nhập lại.')
    }
    loading.value = true
    error.value = null
    try {
      const url = `${supabaseUrl}/functions/v1/export-shift-csv?shiftId=${encodeURIComponent(shiftId)}`
      const res = await fetch(url, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${token}`,
          apikey: import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY ?? '',
        },
      })
      if (!res.ok) {
        const text = await res.text().catch(() => '')
        throw new Error(text || `Export CSV thất bại (HTTP ${res.status})`)
      }
      return await res.text()
    } catch (e) {
      error.value = e instanceof Error ? e.message : String(e)
      throw e
    } finally {
      loading.value = false
    }
  }

  return { loading, error, openShift, closeShift, exportCsv }
}

